s": {"type": "array", "maxItems": 10, "uniqueItems": true, "items": {"type": "string", "pattern": "^[0-9]{15,30}$"}}, "autoCloseMinutes": {"type": "integer", "minimum": 0, "maximum": 43200}, "autoCloseMode": {"type": "string", "enum": ["IDLE", "OPENED"]}, "formEnabled": {"type": "boolean"}, "formTitle": {"type": "string", "minLength": 1, "maxLength": 45}, "fields": {"type": "array", "maxItems": 5, "items": {"type": "object", "required": ["key", "label", "style", "required", "placeholder"], "properties": {"key": {"type": "string", "pattern": "^[a-z0-9_-]{1,32}$"}, "label": {"type": "string", "minLength": 1, "maxLength": 45}, "style": {"type": "string", "enum": ["SHORT", "PARAGRAPH"]}, "required": {"type": "boolean"}, "placeholder": {"type": "string", "maxLength": 100}}}}}}}'::jsonb, '{}'::jsonb, 20);
